#include <iostream>
#include <iomanip>
#include <cctype>
#include <string_view>

void inspect_char(char c) {
    auto uc = static_cast<unsigned char>(c);
    int code = static_cast<int>(uc);
    std::cout << "Char: '";
    if (std::isprint(uc)) {
        std::cout << c;
    } else {
        std::cout << "control";
    }
    std::cout << "' | Decimal: " << std::setw(3) << code
              << " (Row " << (code / 10) << ", Col " << (code % 10) << ")\n";
}

int main() {
    // Inspect characters mentioned in the source page text
    inspect_char('F');
    inspect_char('&');
    inspect_char('0');
    inspect_char('a');

    // Demonstrate arithmetic offset between uppercase and lowercase
    char upper = 'F';
    char lower = static_cast<char>(upper + 32);
    std::cout << upper << " + 32 = " << lower << " (code " << static_cast<int>(lower) << ")\n";

    return 0;
}
